$waEscape=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
$waQuote=static fn(string $value):string=>"'".str_replace("'","'\"'\"'",$value)."'";
$waGet=static fn(string $route,string $params=''):string=>'curl -G '.$waQuote($waDocRoot.$route)." -H 'Authorization: Bearer TU_CLAVE_API'".$params;
$waPost=static function(string $route,array $payload,?string $requestId=null)use($waDocRoot,$waQuote):string{
    $command='curl -X POST '.$waQuote($waDocRoot.$route)." -H 'Authorization: Bearer TU_CLAVE_API' -H 'Content-Type: application/json'";
    if($requestId!==null)$command.=' -H '.$waQuote('Idempotency-Key: '.$requestId);
    return $command.' -d '.$waQuote(json_encode($payload,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE));
};
$waExample=static fn(array $payload,string $requestId):string=>$waPost('v1/whatsapp/send',$payload,$requestId);
