<script>
(()=>{
 const init=()=>document.querySelectorAll('.wa-api-guide').forEach(guide=>{
  if(guide.dataset.searchReady)return;guide.dataset.searchReady='1';
  const input=guide.querySelector('.wa-api-doc-query'),clear=guide.querySelector('.wa-api-doc-clear'),empty=guide.querySelector('.wa-api-doc-empty');if(!input)return;
  const items=[...guide.querySelectorAll('.wa-api-steps article,.wa-api-example,.wa-api-guide-note')];
  const apply=()=>{const query=input.value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();let found=0;
   items.forEach(item=>{const text=item.textContent.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const visible=!query||text.includes(query);item.hidden=!visible;if(visible)found++;});
   clear.hidden=!query;if(empty)empty.hidden=found>0;
  };
  input.addEventListener('input',apply);clear?.addEventListener('click',()=>{input.value='';apply();input.focus()});apply();
 });
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
</script>
